	info := VersionInfo{
		Namespace:   v.Namespace,
		Environment: v.Environment,
		Version:     v.Version,
		RollbackOf:  intPtrOrNil(v.RollbackSource()),
		CreatedAt:   v.CreatedAt,
		Effective:   effectiveVersion != 0 && v.Version == effectiveVersion,
	}
	if v.GrayTag.Valid {
		tag := v.GrayTag.String
		info.GrayTag = &tag
	}
	return info
}

