	for _, change := range body.Changes {
		byName[change.Name] = change
	}
	if len(byName) != 3 {
		t.Fatalf("changes = %v", body.Changes)
	}
	if string(byName["num"].OldValue) != "1" || string(byName["num"].NewValue) != "1.0" {
		t.Fatalf("number semantics changed: %v", byName["num"])
